#include "LaborCatalogue.hpp"
namespace elysium::jobs {bool LaborCatalogue::addLabor(LaborDef l,std::string&w){if(!l.id||!l.family||!l.executorOwner){w="labor row missing owner/family";return false;}return labor_.emplace(l.id,std::move(l)).second;}bool LaborCatalogue::addWorkDetail(WorkDetail d,std::string&w){if(!d.id){w="invalid work detail";return false;}for(auto l:d.allowedLabor)if(!labor_.count(l)){w="work detail references unknown labor";return false;}return details_.emplace(d.id,std::move(d)).second;}bool LaborCatalogue::allowed(ContentId d,ContentId l)const{auto i=details_.find(d);return i!=details_.end()&&i->second.allowedLabor.count(l);}std::optional<LaborDef>LaborCatalogue::get(ContentId id)const{auto i=labor_.find(id);if(i==labor_.end())return std::nullopt;return i->second;}}
